
# ===== THE CELLS — six, each returning out(verdict, effects) =========================================================================
def the_frame(case, data):
    """F1 — Deut 8:1: all the commandment, that you may live and multiply and go in and possess (4:1 by CALL — the readback row), the oath's seats, no receipt"""
    del P_[:]
    ask = case['ask']
    if ask == 'all_the_commandment':
        ink('8:1', '"ALL THE COMMANDMENT which I command you this day you shall keep to do, that you may live and multiply" — "all the commandment" %s (eight seats, all this book\'s); "which I command you this day" %d seats in the book; "and multiply" the form\'s one seat %s; the paragogic nun %s' % (P('כל', 'המצוה'), len(P('אשר', 'אנכי', 'מצוך', 'היום', books=('Deut',))), U('ורביתם'), NUN[1]))
        dat('the frame: no divine frame, no "saying" — the whole chapter Moses\' voice; the second person both numbers at 8:1 (the frame) and 8:19, plural alone at 8:20, singular in sixteen verses, neither at 8:8')
        return out("all the commandment (8:1) — 'all the commandment which I command you this day' the book's eight seats, this the frame's; 'that you may live and multiply' the plural with the nun; no write", ['accepted'])
    if ask == 'live_and_possess':
        ink('8:1', '"that you may live and multiply and go in and possess the land which the LORD swore to your fathers" — "and go in and possess" %s (4:1, 8:1, 11:8 the three seats); "that you may live" %s; the shared run with 4:1 %s' % (P('ובאתם', 'וירשתם'), P('למען', 'תחיון') + P('למען', 'תחיה') + P('למען', 'תחיו'), SHARED(('Deut', 8, 1), ('Deut', 4, 1))))
        move('cold_run_obey_horeb (CALL) — OH.the_exhortation(hear_and_do) = %s' % (OH_HEAR[0][:60],), "4:1's exhortation — 'hear the statutes and the judgments … that you may live and go in and possess the land': the clause said again at the frame; 8:1's 'keep to do' for 4:1's 'hear … to do'")
        dat('the readback row 8:1 VERBATIM in kind — computed %s tokens against 4:1\'s %s, %s shared' % DELTA['live_8_1'])
        return out("live and possess (8:1) — 4:1's exhortation's clause 'that you may live and go in and possess the land' (OH by CALL): the readback row VERBATIM in kind; 4:1, 8:1, 11:8 the three seats", ['accepted'])
    if ask == 'the_oath_seats':
        ink('8:1, 8:18', '"which the LORD swore to your fathers" (8:1) … "his covenant which he swore to your fathers" (8:18) — the swearing verb (the lemma %s) no number, the book\'s %d seats; the oath\'s NOUN (7:8\'s, the lemma 7621) absent from the chapter %s; "which he swore to your fathers" %s' % (lemma_of('Deut', 8, 1, 'נשבע'), len(LEMV('7650', books=('Deut',))), [x for x, l in zip(W8(1) + W8(18), byl[('Deut', 8, 1)] + byl[('Deut', 8, 18)]) if l == '7621'], P('אשר', 'נשבע', 'לאבתיך')))
        move('cold_run_seven_nations (CALL) — SN.the_holy_people(the_oath) = %s' % (SN_OATH[0][:70],), "7:8's form on the oath's three tape lines — sworn_by_himself (Genesis 22:16-18), oath_upheld (26:3-5), visitation_promised (50:24): the noun starred there, the verb here unstarred, no number")
        return out("the oath's seats (8:1, 8:18) — 'swore' twice, no number (7:8's noun the parser's star; here the verb alone): the oath's three lines on the tape (SN by CALL); Onkelos 'established' for 'swore' at both", ['accepted'])
    if ask == 'no_receipt':
        ink('8:1-20', 'the register gate\'s finder\'s rule on the chapter (as/according to all that … commanded … the LORD): seats %s (chapter 5\'s %s and chapter 1\'s %s for the rule\'s witness); "which I command you" (8:1, 8:11) the GIVING, not a receipt' % (receipt_seats(8), receipt_seats(5), receipt_seats(1)))
        dat("the register gate --strict unmoved: DECLARED 100, no seat in chapter 8 (the design's measurement)")
        return out("no receipt (8:1-20) — the register gate's finder (as / according to all that … commanded … the LORD) finds no seat in the chapter: 'which I command you' the giving, not a receipt; DECLARED 100 unmoved", ['accepted'])
    return out('no verdict in span', [FX.NONE])


def the_way_of_forty_years(case, data):
    """F2 — Deut 8:2-6: the forty years (the decree by kind, SL by CALL), the test (16:4's clause), the humbling (the analogy's guards), the manna (ES and BH by CALL), not by bread alone, THE GARMENT AND THE FOOT (the fifth form — SUPPLIED), the discipline (1:31 by CALL), walk and fear"""
    del P_[:]
    ask = case['ask']
    if ask == 'forty_years':
        ink('8:2, 8:4', '"these FORTY years" — the parser\'s [%d] at 8:2 and 8:4 (2:7 the same phrase %s; the wilderness\'s forty at every seat: 16:35 %s, 14:33 %s, 14:34 %s, 32:13 %s); "and you shall remember all the way which the LORD your God led you" — "all the way" %s' % (FORTY, P('זה', 'ארבעים', 'שנה'), N('Exod', 16, 35), N('Num', 14, 33), N('Num', 14, 34), N('Num', 32, 13), P('את', 'כל', 'הדרך')))
        move('cold_run_shelach (CALL) — SL.decree(day_for_year) = %s; cold_run_exodus_story (CALL) — ES.manna(forty_years) = %s' % (SL_DAY[0][:60], ES_FORTY['v']), "the decree's years (Numbers 14:26-35 — decree_declared with years 40, a day for a year) and the manna's forty (16:35): the tape's line found by kind and first verse")
        dat('the readback row 8:2 EXPANDED — computed %s tokens against 14:33-34\'s %s, %s shared: the purpose supplied (the humbling, the test, the heart)' % DELTA['forty_8_2'])
        return out("forty years (8:2, 8:4) — [40] twice, 2:7 the same phrase; the decree's years (SL by CALL: [40, 40] a day for a year; ES's forty years of manna): the readback row 8:2 EXPANDED — the purpose supplied", ['accepted'])
    if ask == 'the_test':
        ink('8:2', '"to humble you, TO TEST YOU, to know what was in your heart, WHETHER you would keep his commandments OR NOT" — the two closing tokens at seven Bible seats %s (Exodus 16:4 the manna\'s own test clause); the interrogative he on a verb the book\'s one %s; the test verb\'s fifteen Torah seats %s' % (WHETHER, [(s, x) for s, x, m in LEMT('8104', books=('Deut',)) if m and m.startswith('HTi')], [s for s, _ in TEST_SEATS]))
        move('cold_run_exodus_story (CALL) — ES.trials(ten_list) = %s, (count_by_exodus) = %s; cold_run_mamre (CALL) — MA.moriah(test_verb_seats) = %s' % (ES_TRIALS['v'], ES_SIX['v'], MA_TEST['v']), "the trials' direction REVERSED — Israel tested God ten times (Arakhin 15a; six by the exodus), here God tests Israel by the manna (16:4 'that I may test them'); the Akedah's verb (22:1) the same lemma")
        dat('the readback row 8:2 VERBATIM in kind — computed %s tokens against 16:4\'s %s, %s shared (the two closing tokens)' % DELTA['whether_8_2'])
        dat('the row the_interrogative_he: %s' % (data['the_interrogative_he']['value'],))
        return out("the test (8:2) — 'whether you would keep his commandments or not': the manna's own test clause (Exodus 16:4 — the readback row VERBATIM in kind), the book's one interrogative he; the trials' direction reversed (ES by CALL: Israel tested God six times by the exodus; here God tests Israel); the Akedah's verb (MA by CALL)", ['accepted'])
    if ask == 'the_humbling':
        ink('8:2-3, 8:16', '"to HUMBLE you … and he HUMBLED you and let you hunger" — the verb\'s seven Deuteronomy seats %s (8:2, 3, 16; the seduced and the ravished; 26:6 the Egyptians\' "afflicted us"); the narrative verbs of the chapter %s' % ([(s, x) for s, x, m in LEMT('6031 b', books=('Deut',))], REG[3]))
        move('Yoma 74b:11-13 (opened whole); Ketubot 47b:11', "the Day's affliction is HUNGER by the verbal analogy with 8:3 (the school of R. Yishmael) — guarded twice: not from Laban's daughters (the PUBLIC's affliction from the public's), not from Egypt's affliction (26:7 — BY THE HAND OF GOD from God's hand): the shelf reads 8:3's hunger as God's act on the whole people; 'onata' sustenance from 8:3 (R. Elazar)")
        return out("the humbling (8:2-3, 8:16) — 'to humble you … he humbled you and let you hunger': the verb's seven Deuteronomy seats; the Day's affliction is HUNGER by the verbal analogy with 8:3 (Yoma 74b:11) — the analogy guarded twice: the public's affliction from the public's, God's hand from God's hand (74b:12-13); Onkelos 'afflict'", ['accepted'])
    if ask == 'the_manna':
        ink('8:3, 8:16', '"and fed you THE MANNA which you did not know, nor did your fathers know" (8:3) … "who fed you manna in the wilderness which your fathers did not know" (8:16) — the manna\'s thirteen seats %s; "nor did your fathers know" %s alone; the doublet\'s diff %s' % ([s for s, _ in MANNA_SEATS], P('ידעון', 'אבתיך'), DIFF(('Deut', 8, 3), ('Deut', 8, 16))))
        move('cold_run_exodus_story (CALL) — ES.manna(day_by_day) = %s; cold_run_beha (CALL) — BH.taberah_and_quail(manna_taste) = %s, (five_foods) = %s' % (ES_DAY['v'], BH_TASTE[0][:40], BH_FIVE[0][:60]), "the tape's manna_fell (Exodus 16:13-15 with 16:4's test clause) and the craving's manna described (Numbers 11:7-9 — the tastes by age, the five foods, R. Ami and R. Asi at Yoma 75a); the affliction IN the manna (74b:14: no bread in the basket / not seen as it tastes)")
        dat('the readback rows 8:3 TURNED (computed %s tokens against 16:15\'s %s, %s shared — the hunger God\'s act, the murmuring\'s occasion made the humbling\'s means) and 8:16 EXPANDED (%s against 8:3\'s %s, %s shared — "to do you good in your end")' % (DELTA['manna_8_3'] + DELTA['manna_8_16']))
        dat("manna_provided on Israel STANDS — a reference, no second write (CU5)")
        return out("the manna (8:3, 8:16) — 'fed you the manna which you did not know, nor did your fathers know': the tape's manna_fell (Exodus 16:13-15; ES by CALL — day by day, forty years) and the craving's manna (Numbers 11 — BH by CALL: the tastes, the five foods): the readback rows 8:3 TURNED (the hunger God's act, the murmuring's occasion the humbling's means) and 8:16 EXPANDED ('to do you good in your end'); manna_provided stands, no second write", ['accepted'])
    if ask == 'not_by_bread_alone':
        ink('8:3', '"that he might make you know that NOT BY BREAD ALONE does man live, but by EVERYTHING THAT PROCEEDS FROM THE MOUTH OF THE LORD does man live" — %s and %s one seat each; "man shall live" %s; "the mouth of the LORD" %d Torah seats; "and live by them" %s (the sanctions\' living)' % (P('לא', 'על', 'הלחם', 'לבדו'), P('כל', 'מוצא', 'פי', 'יהוה'), P('יחיה', 'האדם'), len(P('פי', 'יהוה', books=T)), P('וחי', 'בהם')))
        move('the Sifrei on Deuteronomy 48:10 (read whole at the reading); Yoma 74b:14, 76a:2-3 (opened whole); cold_run_sanctions (CALL) — SA.frame(live_by_them, private) = %s' % (SA_LIVE['v'],), "'not by bread alone' = the exposition; 'everything that proceeds' = the laws and the homilies (R. Shimon ben Menasya); the daily manna's reason — the king's one son, 'everyone's heart to their Father in Heaven every day'; Leviticus 18:5's 'live by them, not die by them' the living's kin")
        dat('the row not_by_bread_alone: %s' % (data['not_by_bread_alone']['value'],))
        return out("not by bread alone (8:3) — 'but by everything that proceeds from the mouth of the LORD': a teaching, not an act (the Sifrei 48:10 — the exposition; Onkelos 'the Word of the LORD'); the daily manna's reason on the shelf — everyone's heart to Heaven every day (Yoma 76a:2-3); 18:5's living by CALL: a DATA row, no write", ['accepted'])
    if ask == 'the_garment_and_the_foot':
        ink('8:4', '"YOUR GARMENT DID NOT WEAR OUT upon you, nor did YOUR FOOT SWELL, these forty years" — "your garment did not wear out" %s (29:4 the plural garments); "did not swell" the verb\'s TWO Bible seats %s; a STATE over [%d] years, the negatives the past (the prohibition form nowhere here %s)' % (GARMENT, SWELL, FORTY, PRO[4]))
        dat("THE READBACK'S FIFTH FORM — THE RETELLING OF A STATE: no line on the tape (an act has a day; a forty-year condition has none), NO ENTRY on any ledger (the one database's run_ledger scanned for a garment, clothing, a shoe or a swelling on israel_people: %s; CU7 the same scan on the running world) — graded SUPPLIED with NO retrograde write (the design's decision, open to the owner); the row the_garment_and_the_foot: %s" % (GARMENT_SCAN, data['the_garment_and_the_foot']['value']['the_state']))
        move("Onkelos 8:4 (read whole at the reading); the docket's scan", "'your shoes did not go bare' — the Aramaic reads the shoe where the Hebrew reads the foot (8:4, 29:4); NO ROW ON THE SHELF cites 8:4 (the scan: the ten verses cited by no one)")
        return out("the garment and the foot (8:4) — a STATE over forty years told only here (29:4 the plural garments; Nehemiah 9:21 the only other 'did not swell'; Onkelos 'your shoes did not go bare'): no line on the tape, no entry on any ledger (the scan empty) — the readback's FIFTH FORM, graded SUPPLIED with NO retrograde write (a condition has no day); cited by no row on the shelf", ['accepted'])
    if ask == 'the_discipline':
        ink('8:5', '"and you shall know with your heart that AS A MAN DISCIPLINES HIS SON, so the LORD your God disciplines you" — %s one seat; "as a man … his son" %s (1:31 the carrying, 2 Kings 23:10 Molech); the discipline-lemma\'s Torah seats %s; "with your heart" %s' % (P('כאשר', 'ייסר', 'איש', 'את', 'בנו'), P('איש', 'את', 'בנו'), [s for s, _, _ in LEMT('3256', books=T)], P('עם', 'לבבך', books=('Deut',))))
        move('cold_run_opening_speech (CALL) — OS.the_spies_read_back(the_carrying) = %s; Berakhot 5a:10, 5a:20-22 (opened whole); the Sifrei 32:10-15 (credited)' % (OS_CARRY[0][:60],), "1:31's 'as a man carries his son' made the discipline — the two seats of the form; the afflictions of love ('as a father the son in whom he delights', Proverbs 3:12); THE LAND ACQUIRED THROUGH SUFFERING — the second of R. Shimon ben Yochai's three gifts: 'as a man rebukes his son' (8:5) and thereafter 'a good land' (8:7)")
        dat('the readback row 8:5 VARIANT — computed %s tokens against 1:31\'s %s, %s shared (carried → disciplined)' % DELTA['discipline_8_5'])
        return out("the discipline (8:5) — 'as a man disciplines his son, so the LORD your God disciplines you': 1:31's carrying made the discipline (OS by CALL — the readback row VARIANT); the Land acquired through suffering, the second of three gifts (Berakhot 5a:20-22; the afflictions of love 5a:10); Onkelos 'teaches'", ['accepted'])
    if ask == 'keep_walk_fear':
        ink('8:6', '"and you shall keep the commandments of the LORD your God, to walk in his ways and to fear him" — "to walk in his ways" %s; "in ALL his ways" %s; "and to fear him" %s one seat; "to fear the LORD" in the book %s' % (P('ללכת', 'בדרכיו'), P('ללכת', 'בכל', 'דרכיו'), P('וליראה', 'אתו'), sorted(set(P('ליראה', 'את', 'יהוה', books=('Deut',))))))
        dat("10:12's 'what does the LORD your God ask of you' forward; Onkelos supplies 'the ways that are RIGHT BEFORE HIM' (8:6, 19:9, 26:17, 28:9, 30:16 — the five seats of the supplement)")
        return out("keep, walk, fear (8:6) — 'to walk in his ways' 8:6, 30:16 and Solomon's charge; 'to fear him' the one seat; 10:12's 'what does the LORD your God ask of you' forward; Onkelos supplies 'right before him': a DATA note, no write", ['accepted'])
    if ask == 'the_messianic_forty':
        ink('8:3', '"and he afflicted you" — the verb at 8:3 (%s) and Psalm 90:15 "according to the days you afflicted us"' % (REG[3][0],))
        move('Sanhedrin 99a:5 (opened whole)', "R. Eliezer: the days of the Messiah FORTY YEARS — 'afflicted' here (8:3, the forty-year sojourn) and 'afflicted' there (Psalm 90:15 'the years we saw evil'): a verbal analogy on the verb")
        return out("the messianic forty (8:3) — R. Eliezer: the days of the Messiah forty years, 'afflicted' at 8:3 and Psalm 90:15 a verbal analogy (Sanhedrin 99a): the exam's row on the two [40]s, a DATA note", ['accepted'])
    return out('no verdict in span', [FX.NONE])


def the_good_land(case, data):
    """F3 — Deut 8:7-10: the good land (6:3 and 6:10-11 by CALL — the readback row), the waters, THE SEVEN SPECIES (the order of blessings, the measures), honey without milk, lack nothing (2:7 by CALL), iron and copper, EAT AND BE SATISFIED AND BLESS — THE WRITE (the grace by Torah law; the measure a PARAMETER; the before-blessing; the four blessings; the grace conditional; the persons; the meal's base and end; the first fruits; any language)"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_good_land':
        ink('8:7, 8:10', '"for the LORD your God brings you to A GOOD LAND" (8:7) … "for THE GOOD LAND which he has given you" (8:10) — the twelve seats %s; "brings you" the participle %s; "the good land which he has given you" %s one seat' % (GOOD_LAND, [x for x, m in wm('Deut', 8, 7) if m and re.search(r'V.r', m)], P('הארץ', 'הטבה', 'אשר', 'נתן', 'לך')))
        move('cold_run_hear_o_israel (CALL) — HI.the_header(the_land_flowing) = %s; HI.the_gift_and_the_warning(the_list) = %s' % (HI_FLOW[0][:60], HI_LIST[0][:60]), "6:3's 'a land flowing with milk and honey' and 6:10-11's gift (the cities, the houses, the cisterns, the vineyards and olives) — here the land itself described: the waters, the seven species, iron and copper; HONEY WITHOUT MILK")
        dat('the readback row 8:7-9 EXPANDED — computed %s tokens against 6:10-11\'s %s, %s shared with 6:3' % DELTA['land_8_7_9'])
        return out("the good land (8:7, 8:10) — twelve seats of 'a good land', the chapter's refrain; 6:3's 'flowing with milk and honey' and 6:10-11's gift (HI by CALL): the readback row 8:7-9 EXPANDED — the waters, the seven species, iron and copper; honey without milk", ['accepted'])
    if ask == 'the_waters':
        ink('8:7', '"a land of BROOKS OF WATER, of SPRINGS AND DEEPS flowing out IN THE VALLEY AND IN THE HILL" — "brooks of water" %s; "springs and deeps" %s (the deeps\' Torah seats %s — the Song of the Sea\'s); "in the valley and in the hill" %s; "flowing out" the participle %s' % (P('נחלי', 'מים'), P('עינת', 'ותהמת'), U('תהמת', 'ותהמת', books=T), P('בבקעה', 'ובהר'), [x for x, m in wm('Deut', 8, 7) if x == 'יצאים']))
        move('the Sifrei on Deuteronomy 39:8 (read whole at the reading); Onkelos 8:7', "the Land drinks irrigation water too — 'a land of brooks of water'; Onkelos 'FLOWING brooks of water, fountains of springs and deeps'")
        return out("the waters (8:7) — brooks (three seats), springs and deeps (one — the deeps' Torah seats the Sea's), the valley and the hill (one); the Sifrei 39:8: the Land drinks irrigation water too; Onkelos 'flowing brooks': a DATA note", ['accepted'])
    if ask == 'the_seven_species':
        ink('8:8', '"a land of WHEAT and BARLEY, of VINES and FIG TREES and POMEGRANATES, a land of OLIVE OIL and HONEY" — the one verse in the Bible holding all seven lemmas %s; three or more %s; the lemmas in order %s; "a land" TWICE in the verse' % (SEVEN_SEATS, THREE_OR_MORE, [lemma_of('Deut', 8, 8, x)[0] for x in W8(8)]))
        move('Berakhot 41a:8, 41a:2-7, 41b:4-5 (opened whole); Mishnah Berakhot 6:4', "THE ORDER OF BLESSINGS BY THE VERSE — Rav Yosef (some say R. Yitzchak): each food that precedes in the verse precedes in the blessing (R. Yehuda's arm of Mishnah 6:4 — the seven species first; the Rabbis: whichever he wants; Ulla: the dispute only where the blessings are the same); RAV HAMNUNA'S TWO 'LAND'S — the date second to the second 'land', the pomegranate fifth to the first ('who will give us iron legs to serve you')")
        dat('the row the_seven_species_seat: %s' % (data['the_seven_species_seat']['value'],))
        return out("the seven species (8:8) — the one verse in the Bible holding all seven; THE ORDER OF BLESSINGS BY THE VERSE (Berakhot 41a:8 — each food that precedes in the verse precedes in the blessing; R. Yehuda's arm of Mishnah Berakhot 6:4, Ulla's refinement) and RAV HAMNUNA'S TWO 'LAND'S (41b:5 — the date second to the second 'land', the pomegranate fifth to the first): the eater of dates before pomegranates holds", ['accepted'])
    if ask == 'the_measures_seat':
        ink('8:8', '"a land of wheat and barley, of vines and fig trees and pomegranates, a land of olive oil and honey" — the verse the measures\' seat on the shelf')
        move('Eruvin 4a:11; Sukkah 5b:14; Berakhot 41a:9-41b:3 (opened whole); the Rambam\'s Introduction to the Mishnah 8:23 (a commentary\'s row, read and marked)', "Rav Chanan: the whole verse stated for the Torah's MEASURES — wheat the leprous house's half-loaf, barley the corpse's bone, the vine the nazirite's quarter-log, the fig the Sabbath's carrying, the pomegranate the vessel's hole, the olive most measures ('a land of olive oil' — most of whose measures are olives), the date the Day's; the other amora: the measures are RABBINIC and the verse a support (41b:3); the Rambam: a mnemonic hung on the verse, not its subject")
        dat('the row the_measures_seat: %s' % (data['the_measures_seat']['value'],))
        return out("the measures from the verse (8:8) — Rav Chanan: the whole verse for the Torah's measures (Eruvin 4a; Sukkah 5b; Berakhot 41a:9-41b:3 — wheat the half-loaf, barley the bone, the vine the quarter-log, the fig the carrying, the pomegranate the vessel, the olive most measures, the date the Day's); the measures rabbinic and the verse a support (41b:3); the Rambam: a mnemonic, not the verse's subject: a DATA row", ['accepted'])
    if ask == 'honey_without_milk':
        ink('8:8', '"a land of olive oil and HONEY" — "flowing with milk and honey" %d seats, none in the chapter (%s); the honey-word %d Torah seats' % (MILK_HONEY, [v for v in range(1, 21) if 'חלב' in W8(v)], len(U('דבש', 'ודבש', 'בדבש', 'מדבש', books=T))))
        move('Berakhot 41b:3 (opened whole); Onkelos 8:8', "'honey' the DATE's — the Day's measure a large date (41b:3); Onkelos 'a land whose olives make oil and which makes honey' (the two supplements)")
        dat('the row honey_without_milk: %s' % (data['honey_without_milk']['value'],))
        return out("honey without milk (8:8) — 'a land of olive oil and honey': 'flowing with milk and honey' twenty seats, none here — the honey the fruit's (the date's, Berakhot 41b:3; Onkelos 'which makes honey'), not the herd's: a DATA row", ['accepted'])
    if ask == 'lack_nothing':
        ink('8:9', '"a land in which you shall eat bread WITHOUT POVERTY, YOU SHALL NOT LACK ANYTHING in it" — "in poverty" the lemma\'s one seat %s; "you shall not lack anything" %s (2:7 "you lacked nothing" %s); the lack-lemma\'s Torah seats %d; the prohibition form a PROMISE %s' % ([(s, x) for s, x, m in LEMT('4544')], P('לא', 'תחסר', 'כל'), P('לא', 'חסרת', 'דבר'), len(LEMT('2637', books=T)), PRO[9]))
        move('cold_run_opening_speech (CALL) — OS.the_bypass(forty_years_lacking_nothing) = %s; Berakhot 36b:15, Sukkah 35a:2, Yoma 81b:6 (credited — the quick look); Berakhot 35b:7 (opened whole)' % (OS_LACK[0][:60],), "2:7's receipt 'these forty years the LORD your God has been with you; you have lacked nothing' — the promise here; R. Meir's PEPPER TREE obligated in orla (the first years' fruit) because 'the Land lacks nothing'; 28:48's 'in hunger, in thirst, in nakedness and IN WANT OF ALL THINGS' the curse that inverts the verse (chapter 28 forward)")
        dat('the readback row 8:9 VERBATIM in kind — computed %s tokens against 2:7\'s %s, %s shared' % DELTA['lack_8_9'])
